const response = await diom.admin.authToken.create(
    {
        name: "some token name",
        role: "some token role",
        expiry: Temporal.Duration.from({ seconds: 30 }),
        enabled: true,
    },
);

let response = diom.admin()
    .auth_token()
    .create(
        AdminAuthTokenCreateIn::new(
            "some token name".to_owned(),
            "some token role".to_owned(),
        )
            .with_expiry(Duration::from_secs(30))
            .with_enabled(true),
    )
    .await?;

const response = await diom.admin.authToken.expire(
    {
        id: "key_06etngr201xwv7qj08mt4cs03w",
        expiry: Temporal.Duration.from({ seconds: 30 }),
    },
);

const response = await diom.admin.authToken.list(
    {
        limit: 1,
        iterator: "key_06etngr201xwv7qj08mt4cs03w",
    },
);

const response = await diom.admin.authToken.update(
    {
        id: "key_06etngr201xwv7qj08mt4cs03w",
        name: "some token name",
        expiry: Temporal.Duration.from({ seconds: 30 }),
        enabled: true,
    },
);

const response = await diom.admin.authRole.configure(
    {
        id: "some_role_id",
        description: "role description…",
        rules: [],
        policies: [],
        context: {},
    },
);

const response = await diom.admin.authRole.list(
    {
        limit: 1,
        iterator: "some_role_id",
    },
);

const response = await diom.admin.authPolicy.configure(
    {
        id: "some_access_policy",
        description: "policy description…",
        rules: [],
    },
);

const response = await diom.admin.authPolicy.list(
    {
        limit: 1,
        iterator: "some_access_policy",
    },
);

const response = await diom.cache.set(
    "some_key",
    [],
    {
        namespace: "some_namespace",
        key: "some_key",
        value: [],
        ttl: Temporal.Duration.from({ seconds: 30 }),
    },
);

const response = await diom.cache.get(
    "some_key",
    {
        namespace: "some_namespace",
        key: "some_key",
        consistency: Consistency.Strong,
    },
);

const response = await diom.cache.namespace.configure(
    {
        name: "some_namespace",
        evictionPolicy: EvictionPolicy.NoEviction,
    },
);

const response = await diom.cache.delete(
    "some_key",
    {
        namespace: "some_namespace",
        key: "some_key",
    },
);

const response = await diom.kv.set(
    "some_key",
    [],
    {
        namespace: "some_namespace",
        key: "some_key",
        value: [],
        ttl: Temporal.Duration.from({ seconds: 30 }),
        behavior: OperationBehavior.Upsert,
        version: 1,
    },
);

const response = await diom.kv.get(
    "some_key",
    {
        namespace: "some_namespace",
        key: "some_key",
        consistency: Consistency.Strong,
    },
);

const response = await diom.kv.delete(
    "some_key",
    {
        namespace: "some_namespace",
        key: "some_key",
        version: 1,
    },
);

const response = await diom.rateLimit.limit(
    {
        namespace: "some_namespace",
        key: "some_key",
        tokens: 1,
        config: {
            capacity: 1,
            refillAmount: 1,
            refillInterval: Temporal.Duration.from({ seconds: 30 }),
        },
    },
);

const response = await diom.rateLimit.getRemaining(
    {
        namespace: "some_namespace",
        key: "some_key",
        config: {
            capacity: 1,
            refillAmount: 1,
            refillInterval: Temporal.Duration.from({ seconds: 30 }),
        },
    },
);

const response = await diom.rateLimit.reset(
    {
        namespace: "some_namespace",
        key: "some_key",
        config: {
            capacity: 1,
            refillAmount: 1,
            refillInterval: Temporal.Duration.from({ seconds: 30 }),
        },
    },
);

const response = await diom.idempotency.start(
    "some_key",
    {
        namespace: "some_namespace",
        key: "some_key",
        lockPeriod: Temporal.Duration.from({ seconds: 30 }),
    },
);

const response = await diom.idempotency.complete(
    "some_key",
    {
        namespace: "some_namespace",
        key: "some_key",
        response: [],
        context: {},
        ttl: Temporal.Duration.from({ seconds: 30 }),
    },
);

let response = diom.idempotency()
    .complete(
        "some_key".to_owned(),
        IdempotencyCompleteIn::new(
            vec![],
            Duration::from_secs(30),
        )
            .with_namespace("some_namespace".to_owned())
            .with_context(HashMap::new()),
    )
    .await?;

const response = await diom.idempotency.abort(
    "some_key",
    {
        namespace: "some_namespace",
        key: "some_key",
    },
);

const response = await diom.msgs.namespace.configure(
    "some_namespace",
    {
        name: "some_namespace",
        retention: {
            period: Temporal.Duration.from({ seconds: 30 }),
        },
    },
);

const response = await diom.msgs.publish(
    "some_topic_name",
    {
        namespace: "some_namespace",
        topic: "some_topic_name",
        msgs: [],
        idempotencyKey: "my_idempotency_key",
    },
);

const response = await diom.msgs.stream.receive(
    "some_topic_name",
    "some_consumer_group",
    {
        namespace: "some_namespace",
        topic: "some_topic_name",
        consumerGroup: "some_consumer_group",
        batchSize: 1,
        leaseDuration: Temporal.Duration.from({ seconds: 30 }),
        defaultStartingPosition: SeekPosition.Earliest,
        batchWait: Temporal.Duration.from({ seconds: 30 }),
    },
);

const response = await diom.msgs.stream.commit(
    "some_topic_name~0",
    "some_consumer_group",
    {
        namespace: "some_namespace",
        topic: "some_topic_name~0",
        consumerGroup: "some_consumer_group",
        offset: 1,
    },
);

const response = await diom.msgs.stream.seek(
    "some_topic_name",
    "some_consumer_group",
    {
        namespace: "some_namespace",
        topic: "some_topic_name",
        consumerGroup: "some_consumer_group",
        offset: 1,
        position: SeekPosition.Earliest,
        timestamp: new Date("2026-04-20 12:00:00Z"),
    },
);

const response = await diom.msgs.stream.cancelLease(
    "some_topic_name~0",
    "some_consumer_group",
    {
        namespace: "some_namespace",
        topic: "some_topic_name~0",
        consumerGroup: "some_consumer_group",
    },
);

const response = await diom.msgs.queue.receive(
    "some_topic_name",
    "some_consumer_group",
    {
        namespace: "some_namespace",
        topic: "some_topic_name",
        consumerGroup: "some_consumer_group",
        batchSize: 1,
        leaseDuration: Temporal.Duration.from({ seconds: 30 }),
        batchWait: Temporal.Duration.from({ seconds: 30 }),
    },
);

const response = await diom.msgs.queue.ack(
    "some_topic_name",
    "some_consumer_group",
    {
        namespace: "some_namespace",
        topic: "some_topic_name",
        consumerGroup: "some_consumer_group",
        msgIds: [],
    },
);

const response = await diom.msgs.queue.extendLease(
    "some_topic_name",
    "some_consumer_group",
    {
        namespace: "some_namespace",
        topic: "some_topic_name",
        consumerGroup: "some_consumer_group",
        msgIds: [],
        leaseDuration: Temporal.Duration.from({ seconds: 30 }),
    },
);

const response = await diom.msgs.queue.configure(
    "some_topic_name",
    "some_consumer_group",
    {
        namespace: "some_namespace",
        topic: "some_topic_name",
        consumerGroup: "some_consumer_group",
        retrySchedule: [],
        dlqTopic: "some_topic_name",
    },
);

const response = await diom.msgs.queue.nack(
    "some_topic_name",
    "some_consumer_group",
    {
        namespace: "some_namespace",
        topic: "some_topic_name",
        consumerGroup: "some_consumer_group",
        msgIds: [],
    },
);

const response = await diom.msgs.queue.redriveDlq(
    "some_topic_name",
    "some_consumer_group",
    {
        namespace: "some_namespace",
        topic: "some_topic_name",
        consumerGroup: "some_consumer_group",
    },
);

const response = await diom.msgs.topic.configure(
    "some_topic_name",
    {
        namespace: "some_namespace",
        topic: "some_topic_name",
        partitions: 1,
    },
);
